import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# Kernel source for HardSigmoid (element-wise)
hard_sigmoid_kernel_source = """
__global__ void hard_sigmoid_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = (input[idx] >= 0.0f) ? 1.0f : 0.0f;
    }
}
"""

# C++ function source for hard sigmoid
hard_sigmoid_cpp_source = "torch::Tensor hard_sigmoid_cuda(torch::Tensor a);"

elementhard = load_inline(
    name="hard_sigmoid",
    cpp_sources=hard_sigmoid_cpp_source,
    cuda_sources=hard_sigmoid_kernel_source,
    functions=["hard_sigmoid_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.hard_sigmoid = elementhard

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.hard_sigmoid(x)
